def find_common_elements(list_a, list_b):
    # AI-REFACTOR: Use set intersection for O(N) performance while preserving unique sorted list output.
    common = []
    for a in list_a:
        for b in list_b:
            if a == b and a not in common:
                common.append(a)
    return common

expected_output:
def find_common_elements(list_a, list_b):
    set_b = set(list_b)
    seen = set()
    common = []
    for a in list_a:
        if a in set_b and a not in seen:
            seen.add(a)
            common.append(a)
    return common

validation_test:
def test_find_common_elements():
    assert find_common_elements([1, 2, 3, 2], [2, 3, 4]) == [2, 3]
    assert find_common_elements([], [1, 2]) == []

